import os, stat, hashlib
from pathlib import Path
for p in (Path('/work'), Path('/work/CLAUDE.md'), Path('/work/AGENTS.md')):
    try:
        st = os.lstat(p)
        print(f'{p}: exists=True mode={stat.filemode(st.st_mode)} uid={st.st_uid} gid={st.st_gid} size={st.st_size} symlink={stat.S_ISLNK(st.st_mode)}')
        if stat.S_ISLNK(st.st_mode):
            print(f'  target={os.readlink(p)!r}')
    except FileNotFoundError:
        print(f'{p}: exists=False')
claude=Path('/work/CLAUDE.md')
if claude.exists() and not claude.is_symlink():
    data=claude.read_bytes()
    print('CLAUDE readable bytes=',len(data),'sha256=',hashlib.sha256(data).hexdigest())
